        margin_pos_lower_edge = True
        detail = []
        for r in rows:
            dB, dM = r["_db"], r["_dm"]
            Dt = dM + off
            deg_clause = (Dt >= dB + 1) and (Dt >= dM + 1)
            ok_deg_both &= deg_clause
            A = r["A"]
            lo_B = a_value(571, r["m"], "MI-1") + S_B(571, Dt - 1, 3.0) - RHO571[c]
            lo_M = a_value(571, r["m"], "MI-1") + S_M(571, Dt - 1, 3.0) - RHO571[c] if Dt - 1 >= 0 else None
            margin_pos_lower_edge &= (lo_M is not None and lo_M > 0)
            if r["m"] in (2, 3, 12, 30):
                detail.append({"m": r["m"], "D*_B": r["D*_B"], "D*_M": r["D*_M"], "D_true": Dt,
