import importlib.util, io, contextlib, re, os, json
spec = importlib.util.spec_from_file_location("s04", "s04_words.py")
mod = importlib.util.module_from_spec(spec)
with contextlib.redirect_stdout(io.StringIO()):
    spec.loader.exec_module(mod)
pats = [r"\bbreak(s|ing|down)?\b", r"\bbroken\b", r"\bclosure\b", r"\bclose[sd]?\b", r"\bopen(s|ed|ing)?\b",
        r"\bbeats?\b", r"\bwins?\b", r"\bweaker\b", r"\bsecurity\b", r"\bunsafe\b", r"\bsettles?\b"]
hits = []
for fname in mod.FILES:
    lines = open(os.path.join(mod.OBJ, fname), encoding="utf-8").read().split("\n")
    P = mod.paths([l + "\n" for l in lines])
    for i, ln in enumerate(lines):
        for p in pats:
            for mm in re.finditer(p, ln, flags=re.I):
                st = mod.hyp_status(P[i], i + 1, [x + "\n" for x in lines]) if fname == "hyp.yaml" else ("comment" if ln.lstrip().startswith("#") else "in force")
                if st.startswith("superseded"):
                    continue
                hits.append((fname, i + 1, mm.group(0), st, P[i][-50:], ln.strip()[:150]))
print(len(hits))
for h in hits: print(h)

