import json
R=json.load(open("s02.out"))
for name in ("threshold_table_MI1","threshold_table_C_CEIL_T"):
    T=R[name]
    for c in ("K-571","B-571"):
        for key in ("D*_B","D*_M"):
            vals={r["m"]: r[key] for r in T if r["curve"]==c}
            num={m:int(v) for m,v in vals.items() if v.isdigit()}
            print(name, c, key, "m12:", vals[12], "max:", max(num.values()), "at m", [m for m,v in num.items() if v==max(num.values())], "entries later than m12:", [m for m,v in num.items() if v>num[12]])
